#!/bin/bash
# Uninstall script for Langdock
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Langdock..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Langdock if running..."
pkill -f "Langdock" 2>/dev/null || true

# Remove /Applications/Langdock.app
echo "Removing /Applications/Langdock.app..."
if [ -d "/Applications/Langdock.app" ]; then
    rm -rf "/Applications/Langdock.app" 2>/dev/null || true
elif [ -f "/Applications/Langdock.app" ]; then
    rm -f "/Applications/Langdock.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/com.langdock.desktop.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/langdock
echo "Removing $HOME/Library/Application Support/langdock..."
if [ -d "$HOME/Library/Application Support/langdock" ]; then
    rm -rf "$HOME/Library/Application Support/langdock" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/langdock" ]; then
    rm -f "$HOME/Library/Application Support/langdock" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/Langdock
echo "Removing $HOME/Library/Logs/Langdock..."
if [ -d "$HOME/Library/Logs/Langdock" ]; then
    rm -rf "$HOME/Library/Logs/Langdock" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/Langdock" ]; then
    rm -f "$HOME/Library/Logs/Langdock" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.langdock.desktop.plist
echo "Removing $HOME/Library/Preferences/com.langdock.desktop.plist..."
if [ -d "$HOME/Library/Preferences/com.langdock.desktop.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.langdock.desktop.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.langdock.desktop.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.langdock.desktop.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
